for user in records:
    if user.has_group("base.group_user") and not user.employee_ids:
        env["hr.employee"].sudo().create({
            "name": user.name,
            "user_id": user.id,
            "work_email": user.login,
            # "department_id": ...,  # TODO: set the target department here
        })
